fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since the two input vectors have the same length,
    // we can zip them and compute element-wise OR.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x | y)
     .collect()
}